export interface RetryOptions {
  retries: number;
  delayMs: number;
  signal?: AbortSignal;
}

/** Retry an async operation with a fixed delay between attempts. */
export async function retry<T>(fn: () => Promise<T>, opts: RetryOptions): Promise<T> {
  let attempt = 0;
  for (;;) {
    try {
      return await fn();
    } catch (err) {
      attempt += 1;
      if (attempt >= opts.retries) throw err;
      await new Promise((resolve) => setTimeout(resolve, opts.delayMs));
    }
  }
}

/**
 * Collapse concurrent calls onto one in-flight promise.
 *
 * The double-fetch this fixes was not a retry bug: two callers arriving on an expired token
 * each started their own refresh, and whichever landed second replaced the token the first
 * one was about to use. Sharing the promise makes the second caller await the first's
 * result instead of racing it.
 */
export function single<T>(fn: () => Promise<T>): () => Promise<T> {
  let inFlight: Promise<T> | null = null;
  return () => {
    if (inFlight) return inFlight;
    inFlight = fn().finally(() => {
      inFlight = null;
    });
    return inFlight;
  };
}

import assert from "node:assert/strict";
import test from "node:test";
import { retry, single } from "./retry.ts";

test("retries until success", async () => {
  let calls = 0;
  const result = await retry(
    async () => {
      calls += 1;
      if (calls < 3) throw new Error("not yet");
      return "ok";
    },
    { retries: 5, delayMs: 1 },
  );
  assert.equal(result, "ok");
  assert.equal(calls, 3);
});

test("two concurrent callers share one refresh", async () => {
  let calls = 0;
  const refresh = single(async () => {
    calls += 1;
    await new Promise((resolve) => setTimeout(resolve, 5));
    return `token-${calls}`;
  });
  const [a, b] = await Promise.all([refresh(), refresh()]);
  assert.equal(calls, 1, "the second caller must not start its own refresh");
  assert.equal(a, b);
});

test("a later caller refreshes again once the first settled", async () => {
  let calls = 0;
  const refresh = single(async () => {
    calls += 1;
    return `token-${calls}`;
  });
  assert.equal(await refresh(), "token-1");
  assert.equal(await refresh(), "token-2");
});
